import type { Anchor, DateRange, PolityEntry, PolityKind, Section } from "@/lib/types";
import { c, d, UPDATED, SEED_EDITOR } from "./helpers";
import { periods } from "./periods";

/**
 * Polities across every era, each located by anchors a source ties to it —
 * capitals, dated inscriptions, monuments and ports. Territories drawn from
 * these are envelopes, not borders: real control fluctuated, frontier zones
 * were shared, and many dynasties were for long stretches feudatories of
 * others. Dates are the conventional span of the dynasty as an independent
 * or principal power unless the label says otherwise.
 */

export const a = (name: string, lat: number, lng: number, role = "capital", from?: number, to?: number): Anchor => ({ name, lat, lng, role, from, to });

const DEFAULT_BASIS =
  "Envelope around the capitals, inscriptions and monuments listed, which the cited sources attribute to this polity. Its real extent fluctuated through the period; frontier zones were shared, contested or held through subordinate rulers.";

function periodsFor(r: DateRange): string[] {
  const end = r.end ?? r.start;
  return periods.filter((p) => p.dates && p.dates.start <= end && (p.dates.end ?? p.dates.start) >= r.start).map((p) => p.id);
}

export interface Spec {
  id: string;
  title: string;
  aliases?: string[];
  kind: PolityKind;
  dates: DateRange;
  region: string;
  summary: string;
  anchors: Anchor[];
  zones?: Anchor[][];
  radius?: number;
  cite: string[];
  related?: string[];
  basis?: string;
  confidence?: "documented" | "estimated" | "disputed";
  sections?: Section[];
  evidence?: PolityEntry["evidence"];
}

/** Region names, used to group polities in lists and on the atlas panel. */
export const POLITY_REGION: Record<string, string> = {};

export function make(s: Spec): PolityEntry {
  POLITY_REGION[s.id] = s.region;
  return {
    type: "polity",
    status: "published",
    updated: UPDATED,
    editor: SEED_EDITOR,
    id: s.id,
    title: s.title,
    aliases: s.aliases,
    kind: s.kind,
    summary: s.summary,
    dates: s.dates,
    periods: periodsFor(s.dates),
    capitals: s.anchors.filter((x) => x.role === "capital").map((x) => ({ name: x.name })),
    related: s.related,
    subjects: ["kingdoms-empires"],
    evidence: s.evidence ?? (s.dates.precision === "debated" ? "debated" : "well-supported"),
    cite: s.cite.map((id) => c(id)),
    sections: s.sections ?? [],
    extent: {
      anchors: s.anchors,
      zones: s.zones,
      radius: s.radius,
      basis: s.basis ?? DEFAULT_BASIS,
      confidence: s.confidence ?? "estimated",
    },
  };
}

